import{_ as a,o as l,c as e,a2 as r}from"./chunks/framework.Crpw6aS5.js";const b=JSON.parse('{"title":"可口可乐（The Coca-Cola Company）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/可口可乐.md","filePath":"03_companies/可口可乐.md"}'),o={name:"03_companies/可口可乐.md"};function i(d,t,h,n,s,u){return l(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="可口可乐-the-coca-cola-company" tabindex="-1">可口可乐（The Coca-Cola Company） <a class="header-anchor" href="#可口可乐-the-coca-cola-company" aria-label="Permalink to &quot;可口可乐（The Coca-Cola Company）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>The Coca-Cola Company</td></tr><tr><td>行业</td><td>饮料 / 消费食品</td></tr><tr><td>成立年份</td><td>1886年</td></tr><tr><td>总部</td><td>佐治亚州亚特兰大市</td></tr><tr><td>伯克希尔持股</td><td>约 9%（长期持有）</td></tr><tr><td>首次买入</td><td>1988年</td></tr><tr><td>投资金额</td><td>约 13 亿美元</td></tr><tr><td>买入均价</td><td>约 3.25 美元/股（经拆股调整）</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>可口可乐是全球最大的饮料公司，业务涵盖：</p><ul><li><strong>碳酸饮料</strong>：可口可乐、雪碧、芬达等全球性品牌</li><li><strong>瓶装水与果汁</strong>：Dasani、Minute Maid、Simply 等</li><li><strong>茶与咖啡</strong>：Georgia 咖啡、VitaCoCo 等区域品牌</li><li><strong>运动饮料</strong>：Powerade 与佳得乐竞争</li><li><strong>全球装瓶系统</strong>：通过特许经营装瓶商网络覆盖全球</li></ul><p>可口可乐在全球超过 200 个国家和地区开展业务，日均消耗超过 19 亿份饮料，是全球最具价值的品牌之一。</p><h2 id="与巴菲特的关系" tabindex="-1">与巴菲特的关系 <a class="header-anchor" href="#与巴菲特的关系" aria-label="Permalink to &quot;与巴菲特的关系&quot;">​</a></h2><h3 id="_1988年的历史性买入" tabindex="-1">1988年的历史性买入 <a class="header-anchor" href="#_1988年的历史性买入" aria-label="Permalink to &quot;1988年的历史性买入&quot;">​</a></h3><p>1988年，巴菲特开始大量买入可口可乐股票，这是伯克希尔历史上最重要的投资决策之一。</p><p><strong>投资背景：</strong></p><ul><li>1987年10月股灾之后，股市大幅下跌</li><li>可口可乐股价也从高点回落</li><li>巴菲特认为这是难得的机会</li></ul><p><strong>投资规模：</strong></p><ul><li>总投资约 <strong>13 亿美元</strong></li><li>占伯克希尔当时股票投资组合的约 35%</li><li>买入均价约 3.25 美元/股（拆股调整后）</li></ul><h3 id="战略眼光" tabindex="-1">战略眼光 <a class="header-anchor" href="#战略眼光" aria-label="Permalink to &quot;战略眼光&quot;">​</a></h3><p>巴菲特买入可口可乐的核心理由与其投资哲学高度一致：</p><ol><li><strong>品牌护城河</strong>：可口可乐是全球最强的消费品牌之一</li><li><strong>定价权</strong>：消费者愿意为可口可乐品牌支付溢价</li><li><strong>全球化潜力</strong>：当时海外市场仍有巨大增长空间</li><li><strong>管理层</strong>：当时 CEO 罗伯托·戈伊苏埃塔（Roberto Goizueta）是优秀的管理者</li></ol><h3 id="长期持有与回报" tabindex="-1">长期持有与回报 <a class="header-anchor" href="#长期持有与回报" aria-label="Permalink to &quot;长期持有与回报&quot;">​</a></h3><p>巴菲特对可口可乐的持有超过三十年：</p><table tabindex="0"><thead><tr><th>时期</th><th>表现</th></tr></thead><tbody><tr><td>1988-1998</td><td>股价增长约 10 倍</td></tr><tr><td>1998 年峰值</td><td>可口可乐成为伯克希尔最大持仓</td></tr><tr><td>持有至今</td><td>依然是伯克希尔的标志性持仓</td></tr></tbody></table><p>1998 年之后，可口可乐股价长期盘整，但巴菲特从未减持，始终视为核心持仓。巴菲特曾在 2020 年后小幅增持。</p><h2 id="核心竞争优势" tabindex="-1">核心竞争优势 <a class="header-anchor" href="#核心竞争优势" aria-label="Permalink to &quot;核心竞争优势&quot;">​</a></h2><h3 id="_1-全球最强消费品牌" tabindex="-1">1. 全球最强消费品牌 <a class="header-anchor" href="#_1-全球最强消费品牌" aria-label="Permalink to &quot;1. 全球最强消费品牌&quot;">​</a></h3><ul><li>BrandZ 全球品牌价值排行榜前三常客</li><li>消费者对品牌的认知跨越文化与国界</li><li>&quot;可乐&quot;几乎成为碳酸饮料的代名词</li></ul><h3 id="_2-全球化装瓶特许经营体系" tabindex="-1">2. 全球化装瓶特许经营体系 <a class="header-anchor" href="#_2-全球化装瓶特许经营体系" aria-label="Permalink to &quot;2. 全球化装瓶特许经营体系&quot;">​</a></h3><ul><li>轻资产运营模式：品牌与灌装分离</li><li>特许经营商负责本地化运营</li><li>资本效率高，回报率高</li></ul><h3 id="_3-持续定价能力" tabindex="-1">3. 持续定价能力 <a class="header-anchor" href="#_3-持续定价能力" aria-label="Permalink to &quot;3. 持续定价能力&quot;">​</a></h3><ul><li>产品价格可随通胀上调</li><li>消费者对小幅涨价不敏感</li><li>带来稳定的利润率提升</li></ul><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><blockquote><p>&quot;如果你每天醒来有 10 亿人在等待你提供的产品，你就能非常富有。&quot; —— 1996年</p></blockquote><blockquote><p>&quot;吉列和可口可乐都是伟大的企业，它们的共同点是有巨大的定价权。&quot; —— 1996年</p></blockquote><blockquote><p>&quot;如果你在 1988 年买入可口可乐并持有到今天，你的回报是惊人的。问题是，你能不能在那时候就看到这一点？&quot; —— 股东信</p></blockquote><h2 id="财务表现-摘录" tabindex="-1">财务表现（摘录） <a class="header-anchor" href="#财务表现-摘录" aria-label="Permalink to &quot;财务表现（摘录）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>年份</th><th>营收</th><th>净利润</th><th>备注</th></tr></thead><tbody><tr><td>1988（投资年）</td><td>83亿美元</td><td>8亿美元</td><td>巴菲特开始买入</td></tr><tr><td>1998（高峰期）</td><td>185亿美元</td><td>35亿美元</td><td>股价创历史新高</td></tr><tr><td>2023</td><td>458亿美元</td><td>97亿美元</td><td>持续增长</td></tr></tbody></table><h2 id="相关人物" tabindex="-1">相关人物 <a class="header-anchor" href="#相关人物" aria-label="Permalink to &quot;相关人物&quot;">​</a></h2><ul><li><a href="/search.html?q=罗伯托·戈伊苏埃塔">罗伯托·戈伊苏埃塔</a>（Roberto Goizueta）—— 1981-1997年担任 CEO，卓越的经营者</li></ul><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>1988, 1989, 1991, 1993, 1994, 1995, 1996, 1997, 1998, 1999, 2000, 2003, 2006, 2007, 2008, 2009, 2010, 2011, 2013, 2014, 2016, 2017, 2019, 2020, 2021, 2022, 2023</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a> - 投资主体</li><li><a href="./喜诗糖果.html">喜诗糖果</a> - 同期经典收购案例</li><li><a href="./美国运通.html">美国运通</a> - 同期重要持仓</li><li><a href="./富国银行.html">富国银行</a> - 同期重要持仓</li></ul><hr><p><em>最后更新：2026-04-12</em></p>',42)])])}const p=a(o,[["render",i]]);export{b as __pageData,p as default};
